export type TitleCheck = { ok: true; title: string } | { ok: false; message: string };

/** Trims the title and checks it against the rules of the contract. */
export function checkTitle(title: unknown): TitleCheck {
  if (typeof title !== "string") return { ok: false, message: "Title must be a string." };
  const trimmed = title.trim();
  if (trimmed === "") return { ok: false, message: "A title is required." };
